const FEATURES=[['▦','Dashboard','Indicadores e gráficos para entender seu negócio em segundos.','Básico'],['$','Financeiro','Entradas, saídas, contas, recorrências e fluxo de caixa.','Básico'],['◎','Clientes','Cadastro completo e histórico centralizado de relacionamento.','Básico'],['▣','Agenda','Compromissos, serviços e responsáveis organizados.','Profissional'],['◫','Produtos e serviços','Catálogo, preços, custos e informações sempre atualizados.','Básico'],['↗','Vendas','Registre vendas e atualize todos os módulos automaticamente.','Profissional'],['▥','Estoque','Movimentações, inventário e alertas de estoque baixo.','Completo'],['◧','Relatórios','Filtros e exportações em CSV, Excel e PDF.','Profissional'],['♙','Equipe','Usuários, perfis e permissões granulares.','Completo']];
const PLANS=[{name:'Básico',price:'49,90',users:'1 usuário',items:['Dashboard básico','Clientes','Financeiro básico','Produtos e serviços','Relatórios básicos']},{name:'Profissional',price:'79,90',users:'Até 3 usuários',featured:true,items:['Tudo do plano Básico','Agenda completa','Contas a pagar e receber','Vendas e movimentações','Exportações e dashboard avançado']},{name:'Completo',price:'124,90',users:'Até 10 usuários',items:['Tudo do Profissional','Estoque e alertas','Equipe e permissões','Auditoria detalhada','Relatórios avançados']}];
const FAQ=[['Preciso instalar o MD Flux?','Não. O MD Flux funciona online e pode ser acessado pelo navegador.'],['Consigo acessar pelo celular?','Sim. A plataforma é responsiva para computador, tablet e celular.'],['Meus dados ficam separados das outras empresas?','Sim. Cada empresa possui seu ambiente isolado e políticas de segurança no banco.'],['Posso adicionar usuários?','Sim. A quantidade incluída varia conforme o plano e usuários extras podem ser adicionados.'],['O MD Flux substitui minhas planilhas?','Sim. Ele centraliza os principais controles e mantém os dados conectados.'],['Posso testar antes?','Sim. Use a demonstração para conhecer todos os módulos sem alterar dados reais.'],['Como funciona o pagamento?','Na versão inicial, a contratação é feita pelo WhatsApp e o acesso é liberado após confirmação.']];
const NAV=[['⌂','Dashboard'],['$','Financeiro'],['◎','Clientes'],['□','Agenda'],['◫','Produtos e serviços'],['↗','Vendas'],['▥','Estoque'],['◧','Relatórios'],['♙','Equipe'],['⚙','Configurações']];
const ROWS={Financeiro:[['Venda #1048','Receita','R$ 1.890,00','Pago'],['Aluguel da loja','Despesa','R$ 2.300,00','Pendente'],['Venda #1047','Receita','R$ 740,00','Pago'],['Fornecedor Aurora','Despesa','R$ 980,00','Vencido']],Clientes:[['Clínica Bem Viver','Pessoa jurídica','(16) 99122-4567','Ativo'],['Studio Camila Rocha','Pessoa jurídica','(16) 99741-3310','Ativo'],['Rafael Nogueira','Pessoa física','(16) 98810-4532','Ativo'],['Ateliê Encanto','Pessoa jurídica','(16) 99288-2017','Inativo']],Agenda:[['Reunião comercial','Clínica Bem Viver','Hoje · 09:30','Confirmado'],['Atendimento Studio','Camila Rocha','Hoje · 14:00','Agendado'],['Revisão financeira','Equipe','Hoje · 16:30','Agendado']],['Produtos e serviços']:[['Kit Essencial','KIT-001','R$ 189,90','Ativo'],['Consultoria mensal','SER-003','R$ 650,00','Ativo'],['Produto Aurora','PRO-018','R$ 79,90','Estoque baixo']],Vendas:[['Venda #1048','Clínica Bem Viver','R$ 1.890,00','Concluída'],['Venda #1047','Rafael Nogueira','R$ 740,00','Concluída'],['Venda #1046','Ateliê Encanto','R$ 420,00','Pendente']],Estoque:[['Kit Essencial','38 unidades','Mín. 10','Normal'],['Produto Aurora','4 unidades','Mín. 8','Crítico'],['Linha Premium','12 unidades','Mín. 10','Atenção']],Equipe:[['Mariana Silva','Administradora','Hoje, 08:12','Ativo'],['Lucas Ferreira','Comercial','Ontem, 17:48','Ativo'],['Ana Costa','Financeiro','11/09, 15:20','Ativo']]};
const $=s=>document.querySelector(s), $$=s=>document.querySelectorAll(s);
const CONFIG={whatsapp:'5516997754245',demoUsers:[{login:'demo@mdflux.com.br',password:'MDFlux@2026'},{login:'demo',password:'MDFlux@2026'}]};
$('#feature-grid').innerHTML=FEATURES.map(f=>`<article><span class="feature-icon">${f[0]}</span><h3>${f[1]}</h3><p>${f[2]}</p><small>Disponível no plano ${f[3]} →</small></article>`).join('');
$('#plans-grid').innerHTML=PLANS.map(p=>`<article class="plan ${p.featured?'featured':''}">${p.featured?'<span class="badge">MAIS ESCOLHIDO</span>':''}<h3>${p.name}</h3><div class="price">R$ ${p.price}<small>/mês</small></div><p>${p.users}</p><ul>${p.items.map(x=>`<li>${x}</li>`).join('')}</ul><button class="${p.featured?'primary':'secondary'}" data-action="whatsapp">Quero começar</button></article>`).join('');
$('#faq-list').innerHTML=FAQ.map((f,i)=>`<article class="faq-item"><button class="faq-q" aria-expanded="${i===0}">${f[0]}<span>${i===0?'−':'+'}</span></button><p class="faq-a ${i?'hidden':''}">${f[1]}</p></article>`).join('');
$('#app-nav').innerHTML=NAV.map((n,i)=>`<button class="${i===0?'active':''}" data-module="${n[1]}"><span>${n[0]}</span>${n[1]}</button>`).join('');
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),3000)}
function openLogin(){ $('#login-step-2').classList.add('hidden');$('#login-step-1').classList.remove('hidden');$('#login-email').value='';$('#password').value='';$('#login-modal').classList.remove('hidden');setTimeout(()=>$('#login-email').focus(),50) }
function openDemo(){ $('#marketing').classList.add('hidden');$('.topbar').classList.add('hidden');$('#login-modal').classList.add('hidden');$('#app').classList.remove('hidden');document.body.style.overflow='hidden';renderDashboard() }
function closeApp(){ $('#app').classList.add('hidden');$('#marketing').classList.remove('hidden');$('.topbar').classList.remove('hidden');document.body.style.overflow='';location.hash='home' }
function renderDashboard(){ $$('#app-nav button').forEach(x=>x.classList.toggle('active',x.dataset.module==='Dashboard'));$('#app-content').innerHTML=`<div class="notice">Você está no ambiente de demonstração. Explore todos os recursos livremente.</div><div class="dash-head"><div><h1>Visão geral</h1><p>Acompanhe os principais números da Loja Florescer.</p></div><div class="filters"><button>Hoje</button><button>7 dias</button><button class="active">30 dias</button><button>Este mês</button></div></div><div class="kpi-grid">${[['Saldo atual','R$ 48.320,00','↑ 12,5%'],['Entradas','R$ 31.840,00','↑ 8,2%'],['Saídas','R$ 12.460,00','↓ 3,1%'],['Vendas','86','↑ 14,8%']].map((k,i)=>`<article class="kpi"><div><span>${k[0]}</span><i>${['$','↗','↘','◫'][i]}</i></div><strong>${k[1]}</strong><small>${k[2]} no período</small></article>`).join('')}</div><div class="dash-grid"><article class="panel"><div class="panel-head"><h3>Fluxo de caixa</h3><small>Últimos 7 meses</small></div><div class="chart-large">${[40,63,52,79,68,92,83].map(x=>`<i style="height:${x}%"></i>`).join('')}</div></article><article class="panel"><div class="panel-head"><h3>Próximos compromissos</h3><small>Ver agenda</small></div>${ROWS.Agenda.map(r=>`<div class="list-row"><b>${r[0]}</b><span>${r[1]}</span><small>${r[2]}</small><span>${r[3]}</span></div>`).join('')}</article></div>`;bindFilters()}
function renderModule(name){if(name==='Dashboard')return renderDashboard();const rows=ROWS[name]||[['Relatório mensal','Período atual','Atualizado agora','Disponível'],['Desempenho por categoria','30 dias','Atualizado hoje','Disponível'],['Auditoria de atividades','7 dias','Atualizado hoje','Disponível']];$('#app-content').innerHTML=`<div class="module-head"><div><h1>${name}</h1><p>Visualize, organize e encontre rapidamente suas informações.</p></div><div class="module-tools"><button class="secondary export">Exportar</button><button class="primary new-record">+ Novo registro</button></div></div><div class="filters"><button class="active">Todos</button><button>Ativos</button><button>Pendentes</button><button>Este mês</button></div><div class="table-card"><div class="data-row table-header"><span>Descrição</span><span>Detalhes</span><span>Valor / data</span><span>Status</span></div>${rows.map(r=>`<div class="data-row"><b>${r[0]}</b><span>${r[1]}</span><span>${r[2]}</span><span class="status">${r[3]}</span></div>`).join('')}</div>`;$('.new-record').onclick=()=>{ $('#record-title').textContent=`Novo registro em ${name}`;$('#record-modal').classList.remove('hidden')};$('.export').onclick=()=>exportCsv(name,rows);bindFilters()}
function bindFilters(){ $$('.filters button').forEach(b=>b.onclick=()=>{b.parentElement.querySelectorAll('button').forEach(x=>x.classList.remove('active'));b.classList.add('active');toast(`Filtro “${b.textContent}” aplicado`)}) }
function exportCsv(name,rows){const csv='Descrição,Detalhes,Valor ou data,Status\n'+rows.map(r=>r.map(x=>`"${x}"`).join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=`md-flux-${name.toLowerCase().replaceAll(' ','-')}.csv`;a.click();toast('Relatório CSV exportado com sucesso')}
document.addEventListener('click',e=>{const a=e.target.closest('[data-action]');if(!a)return;const act=a.dataset.action;if(act==='demo'||act==='login')openLogin();if(act==='close')$('#login-modal').classList.add('hidden');if(act==='exit')closeApp();if(act==='close-record')$('#record-modal').classList.add('hidden');if(act==='whatsapp')window.open(`https://wa.me/${CONFIG.whatsapp}?text=`+encodeURIComponent('Olá! Conheci o MD Flux e gostaria de saber mais sobre o sistema.'),'_blank')});
$$('.faq-q').forEach(q=>q.onclick=()=>{const p=q.nextElementSibling,open=!p.classList.contains('hidden');p.classList.toggle('hidden');q.setAttribute('aria-expanded',!open);q.querySelector('span').textContent=open?'+':'−'});
$('#continue-login').onclick=()=>{if(!$('#login-email').value.trim())return toast('Informe seu e-mail ou usuário para continuar');$('#login-step-1').classList.add('hidden');$('#login-step-2').classList.remove('hidden');setTimeout(()=>$('#password').focus(),50)};$('.back-login').onclick=()=>{$('#login-step-2').classList.add('hidden');$('#login-step-1').classList.remove('hidden')};$('#show-pass').onclick=e=>{e.preventDefault();const p=$('#password');p.type=p.type==='password'?'text':'password'};
$('#submit-login').onclick=()=>{const login=$('#login-email').value.trim().toLowerCase(),password=$('#password').value;const valid=CONFIG.demoUsers.some(u=>u.login===login&&u.password===password);if(!valid)return toast('Usuário ou senha inválidos. Confira as credenciais fornecidas.');openDemo()};
$('#login-email').addEventListener('keydown',e=>{if(e.key==='Enter')$('#continue-login').click()});$('#password').addEventListener('keydown',e=>{if(e.key==='Enter')$('#submit-login').click()});
$('#record-form').onsubmit=e=>{e.preventDefault();$('#record-modal').classList.add('hidden');toast('Você está utilizando a demonstração. Contrate um plano para salvar.')};
$('#app-nav').onclick=e=>{const b=e.target.closest('[data-module]');if(!b)return;$$('#app-nav button').forEach(x=>x.classList.remove('active'));b.classList.add('active');renderModule(b.dataset.module);$('.sidebar').classList.remove('open')};$('.app-menu').onclick=()=>$('.sidebar').classList.toggle('open');$('#notif').onclick=()=>toast('3 notificações: estoque baixo, conta vencendo e agendamento próximo');
